<template><div class="app-page"><div class="app-heading"><div><p class="eyebrow">REMOTE REPOSITORY SYNC</p><h2>GitHub <em>activity.</em></h2></div><a :href="profile.github" target="_blank" rel="noreferrer" class="text-link">View profile ↗</a></div><div v-if="loading" class="repo-grid"><div v-for="n in 6" :key="n" class="repo-card loading-card"></div></div><div v-else-if="error" class="empty-state">Repository sync is unavailable right now. <a :href="profile.github" target="_blank" rel="noreferrer">Visit GitHub directly ↗</a></div><div v-else class="repo-grid"><a v-for="repo in repos" :key="repo.id" :href="repo.url" target="_blank" rel="noreferrer" class="repo-card"><p>{{ repo.language || 'Repository' }} <span>★ {{ repo.stars }}</span></p><h3>{{ repo.name }}</h3><small>{{ repo.description || 'A public repository showcasing ongoing work.' }}</small></a></div></div></template>
<script setup>import { onMounted, ref } from 'vue'; import { profile } from '@/data/profile'; import { fetchGitHubRepos } from '@/services/github'; const repos = ref([]); const loading = ref(true); const error = ref(false); onMounted(async () => { try { repos.value = (await fetchGitHubRepos('elgmouriabderrahim')).slice(0, 9); } catch { error.value = true; } finally { loading.value = false; } });</script>
